export function Streaming({
  chunks = "{{chunks}}",
  cursor = {{cursor}},
  accent = "{{accent}}",
}) {
  const showC2 = chunks === "two" || chunks === "three";
  const showC3 = chunks === "three";
  return (
    <div role="status" aria-live="polite" style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
      <p style={{ margin: 0, lineHeight: 1.6 }}>
        <span>The response streams in as tokens arrive.</span>
        {showC2 && <span> No need to wait for the whole reply.</span>}
        {showC3 && <span> Each chunk renders the moment it lands.</span>}
        {cursor && <span className="cursor" style={{ display: "inline-block", width: 7, height: 14, verticalAlign: -2, marginLeft: 2, background: accent }} />}
      </p>
      <p style={{ margin: "10px 0 0", fontSize: 11, color: "#241430aa" }}>{chunks} chunk(s) received so far</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .cursor { animation: lod-str-blink 900ms steps(1) infinite; }
          @keyframes lod-str-blink { 50% { opacity: 0; } }
        }
      `}</style>
    </div>
  );
}
